// Exact source-stage/fused wrapping algorithms shared by native and Wasm.
fn quot(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a/b}}
fn rem(a:u32,b:u32,z:u32)->u32{if b==0{z}else{a%b}}
#[no_mangle]pub extern "C" fn bench_alloc(n:usize)->*mut u32{let mut v=vec![0;n];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle]pub unsafe extern "C" fn bench_free(p:*mut u32,n:usize){drop(Vec::from_raw_parts(p,n,n));}
pub fn bench_scalar(case:u32,xs:&[u32],ys:&[u32],seed:u32,k:u32)->u64{match case{
0=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot((x).wrapping_add(seed),k,seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_add(b)) as u64},
1=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot((x).wrapping_add(seed),k,seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_sub(b)) as u64},
2=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot((x).wrapping_add(seed),k,seed)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x<seed)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x<k){(k).wrapping_sub(x)}else{(x).wrapping_sub(k)})).wrapping_add(seed)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_mul(k).wrapping_add(b.wrapping_mul(3))) as u64},
3=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x>seed){(x).wrapping_sub(seed)}else{(seed).wrapping_sub(x)})).wrapping_mul(3u32)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot(((x).wrapping_mul(k)).wrapping_add(seed),seed,k)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_add(b)) as u64},
4=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x>seed){(x).wrapping_sub(seed)}else{(seed).wrapping_sub(x)})).wrapping_mul(3u32)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot(((x).wrapping_mul(k)).wrapping_add(seed),seed,k)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_sub(b)) as u64},
5=>{let filtered:Vec<u32>=xs.iter().copied().filter(|&x|(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|((if (x>seed){(x).wrapping_sub(seed)}else{(seed).wrapping_sub(x)})).wrapping_mul(3u32)).collect();let mut a=0u32;for x in mapped{a=a.wrapping_add(x);}let filtered:Vec<u32>=xs.iter().copied().filter(|&x|!(x>k)).collect();let mapped:Vec<u32>=filtered.iter().map(|&x|quot(((x).wrapping_mul(k)).wrapping_add(seed),seed,k)).collect();let mut b=0u32;for x in mapped{b=b.wrapping_add(x);}(a.wrapping_mul(k).wrapping_add(b.wrapping_mul(3))) as u64},
_=>panic!("non-scalar case")}}
#[no_mangle]pub unsafe extern "C" fn bench_eval(case:u32,xp:*const u32,xn:usize,yp:*const u32,yn:usize,seed:u32,k:u32,out:*mut u32)->usize{let xs=std::slice::from_raw_parts(xp,xn);let ys=std::slice::from_raw_parts(yp,yn);match case{
0=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
1=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
2=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
3=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
4=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
5=>{*out=bench_scalar(case,xs,ys,seed,k) as u32;1},
6=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (x<seed){(x).wrapping_add(k)}else{(x).wrapping_sub(k)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_mul(k)}else{(x).wrapping_add(seed)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
7=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_add(k)}else{(x).wrapping_sub(seed)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (x<seed){(x).wrapping_add(k)}else{(x).wrapping_sub(k)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
8=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_add(k)}else{(x).wrapping_sub(seed)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_mul(k)}else{(x).wrapping_add(seed)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
9=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (x>k){(x).wrapping_sub(seed)}else{(seed).wrapping_sub(x)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,3u32,0u32)==0u32){(x).wrapping_mul(k)}else{(x).wrapping_add(seed)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
10=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_add(k)}else{(x).wrapping_sub(seed)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (x>k){(x).wrapping_sub(seed)}else{(seed).wrapping_sub(x)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
11=>{let first:Vec<u32>=xs.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,2u32,0u32)==0u32){(x).wrapping_add(k)}else{(x).wrapping_sub(seed)})}).collect();let second:Vec<u32>=first.iter().enumerate().map(|(j,&x)|{let i=j as u32;(if (rem(i,3u32,0u32)==0u32){(x).wrapping_mul(k)}else{(x).wrapping_add(seed)})}).collect();for(j,&value)in second.iter().enumerate(){*out.add(j)=value;}xs.len()},
_=>panic!("unknown case")}}
